def replace_max_specialchar(text, n):
    """Write a function to replace maximum n occurrences of spaces, commas, or dots with a colon."""
    if n <= 0:
        return text
    chars = []
    replaced = 0
    for char in text:
        if replaced < n and char in " ,.":
            chars.append(":")
            replaced += 1
        else:
            chars.append(char)
    return "".join(chars)
